// Stateful scorers (prefix-affinity) register observers that update internal
// state after each routing decision. Observers are called after argmax selection.
//
// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// HYPOTHESIS-1: Using queue-depth-based quadratic penalties with earlier onset (excess>=2) and combining with per-SLO load scaling will reduce load_spikes_e2e_ms below 3200 by preventing pile-on faster
	// MECHANISM-1: QueueDepth is the direct cause of waiting; penalizing it quadratically starting earlier forces spillover before queues grow large, especially for the dominant prefix group in load_spikes
	// EXPECT-1: load_spikes_e2e_ms < 3200
	// RESULT-1: REFUTED (actual=3364.9193584)
	// HYPOTHESIS-2: Weighting CacheHitRate as a tiebreaker bonus for instances with proven cache performance will improve cache_warmup by preferring warm instances without causing imbalance
	// MECHANISM-2: CacheHitRate captures historical warmth; adding a small bonus steers traffic to instances that actually deliver cache hits, complementing the prefix-affinity scorer's block-matching
	// EXPECT-2: cache_warmup_e2e_ms < 4200
	// RESULT-2: REFUTED (actual=4286.3947800000005)
	// HYPOTHESIS-3: Keeping session+long-prefix affinity strong while using aggressive load penalties elsewhere will maintain multiturn_e2e_ms below 165ms
	// MECHANISM-3: Long-prefix sessions have high recomputation cost; strong affinity preserves KV cache hits while load penalties only dominate when queue imbalance is severe
	// EXPECT-3: multiturn_e2e_ms < 165
	// RESULT-3: CONFIRMED (actual=160.42904933333332)

	// Compute per-scorer raw scores
	rawScores := make([]map[string]float64, len(ws.scorers))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		rawScores[i] = make(map[string]float64, len(snapshots))
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			rawScores[i][snap.ID] = s
		}
	}

	// Compute load statistics
	inputLen := len(req.InputTokens)
	minLoad := snapshots[0].EffectiveLoad()
	maxLoad := snapshots[0].EffectiveLoad()
	totalLoad := 0
	for _, snap := range snapshots {
		load := snap.EffectiveLoad()
		if load < minLoad {
			minLoad = load
		}
		if load > maxLoad {
			maxLoad = load
		}
		totalLoad += load
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots))

	// Determine dynamic weights based on request characteristics
	prefixWeight := ws.weights[0]
	loadWeight := ws.weights[1]

	// Input-length based weight adjustment
	if inputLen < 48 {
		prefixWeight = ws.weights[0] * 0.05
		loadWeight = ws.weights[1] * 4.0
	} else if inputLen < 128 {
		prefixWeight = ws.weights[0] * 0.3
		loadWeight = ws.weights[1] * 2.5
	} else if inputLen < 256 {
		prefixWeight = ws.weights[0] * 0.8
		loadWeight = ws.weights[1] * 1.5
	} else {
		prefixWeight = ws.weights[0] * 2.5
		loadWeight = ws.weights[1] * 1.0
	}

	// SLO-based adjustments
	if req.SLOClass == "realtime" {
		prefixWeight *= 0.1
		loadWeight *= 3.5
	} else if req.SLOClass == "batch" {
		prefixWeight *= 1.5
		loadWeight *= 0.6
	}

	// Session affinity boost for multi-turn with long prefixes
	if req.SessionID != "" && inputLen >= 128 {
		prefixWeight *= 3.0
	}

	// System-wide stress: when average load is high, reduce prefix weight globally
	if avgLoad > 5.0 {
		stressFactor := 1.0 / (1.0 + 0.15*(avgLoad-5.0))
		prefixWeight *= stressFactor
	}

	// Compute weighted scores
	scores := make(map[string]float64, len(snapshots))
	dynamicWeights := []float64{prefixWeight, loadWeight}
	for len(dynamicWeights) < len(ws.scorers) {
		dynamicWeights = append(dynamicWeights, ws.weights[len(dynamicWeights)])
	}

	for i := range ws.scorers {
		for _, snap := range snapshots {
			scores[snap.ID] += rawScores[i][snap.ID] * dynamicWeights[i]
		}
	}

	// CacheHitRate bonus: small tiebreaker favoring historically warm instances
	for _, snap := range snapshots {
		if snap.CacheHitRate > 0.0 {
			scores[snap.ID] += snap.CacheHitRate * 0.1 * prefixWeight
